// src/components/Contact.jsx
import { useState } from "react";
import resume from "../data/resume";
import "./Contact.css";

export default function Contact() {
  const [form, setForm] = useState({
    name: "",
    email: "",
    subject: "",
    message: "",
  });

  const handleChange = (e) => {
    setForm({
      ...form,
      [e.target.name]: e.target.value,
    });
  };

  const handleSubmit = (e) => {
    e.preventDefault();

    // Temporary Mailto
    window.location.href = `mailto:${resume.email}?subject=${encodeURIComponent(
      form.subject
    )}&body=${encodeURIComponent(
      `Name: ${form.name}

Email: ${form.email}

${form.message}`
    )}`;
  };

  return (
    <section id="contact" className="contact section section--alt">
      <div className="section__inner">

        <div className="contact__header">
          <p className="section-label">Get In Touch</p>
          <h2 className="section-title">
            Let's Work <em>Together</em>
          </h2>
          <p className="contact__text">
            Have a project in mind or looking for a Flutter Developer?
            Feel free to send me a message and I'll get back to you soon.
          </p>
        </div>

        <div className="contact__container">

          {/* Contact Info */}

          <div className="contact__info">

            <div className="contact__card">
              <h4>Email</h4>
              <a href={`mailto:${resume.email}`}>{resume.email}</a>
            </div>

            <div className="contact__card">
              <h4>Phone</h4>
              <a href={`tel:${resume.phone}`}>{resume.phone}</a>
            </div>

            <div className="contact__card">
              <h4>LinkedIn</h4>
              <a
                href={resume.linkedinUrl}
                target="_blank"
                rel="noreferrer"
              >
                {resume.linkedin}
              </a>
            </div>

            <div className="contact__card">
              <h4>Location</h4>
              <p>{resume.location}</p>
            </div>

          </div>

          {/* Contact Form */}

          <div className="contact__form-card">

            <form onSubmit={handleSubmit} className="contact__form">

              <div className="form__group">
                <input
                  type="text"
                  name="name"
                  placeholder="Your Name"
                  value={form.name}
                  onChange={handleChange}
                  required
                />
              </div>

              <div className="form__group">
                <input
                  type="email"
                  name="email"
                  placeholder="Your Email"
                  value={form.email}
                  onChange={handleChange}
                  required
                />
              </div>

              <div className="form__group">
                <input
                  type="text"
                  name="subject"
                  placeholder="Subject"
                  value={form.subject}
                  onChange={handleChange}
                  required
                />
              </div>

              <div className="form__group">
                <textarea
                  rows="6"
                  name="message"
                  placeholder="Write your message..."
                  value={form.message}
                  onChange={handleChange}
                  required
                />

              </div>

              <button className="btn btn--primary">
                Send Message →
              </button>

            </form>

          </div>

        </div>

      </div>
    </section>
  );
}
